import * as PIXI from 'pixi.js';
import { GameStateModel, GameState } from './models/GameStateModel';
import { NetworkService } from './services/NetworkService';
import { SymbolManager } from './managers/SymbolManager';
import { ReelAnimationManager } from './managers/ReelAnimationManager';
import { ButtonPanel } from './views/ButtonPanel';
import { EventBus, GameEvents } from './core/EventBus';
import { WinPanel } from './views/WinPanel';
import { ReelContainer } from './views/ReelContainer';
import { ResponsiveGameContainer } from './views/ResponsiveGameContainer';
import { BackgroundUI } from './views/BackgroundUI';
import { AssetLoader } from './assets/AssetLoader';
import { GameRound } from './rounds/GameRound';
import { WinEvaluationRound } from './rounds/WinEvaluationRound';
import { WinCelebrationEffect } from './winCelebration/WinCelebrationEffect';
import { createWinCelebrationEffect } from './winCelebration/createWinCelebrationEffect';

export class GameController {
    private stage: ResponsiveGameContainer;
    public readonly backgroundUI: BackgroundUI;
    private gameUI: PIXI.Container;
    private stateModel: GameStateModel;
    private networkService: NetworkService;
    private symbolManager: SymbolManager;
    private animationManager!: ReelAnimationManager;
    private reelContainer!: ReelContainer;
    private hudView!: ButtonPanel;
    private winPanel!: WinPanel;
    private winParticleEffect!: WinCelebrationEffect & PIXI.Container;
    private balance = 1000;
    private bet = 1;
    private roundWin = 10;

    private currentBackground: 'snow' | 'summer' = 'snow';
    private eventBus = EventBus.getInstance();
    private gameRounds: GameRound[] = [];

    constructor(stage: ResponsiveGameContainer) {
        this.stage = stage;
        this.backgroundUI = new BackgroundUI(stage.gameAreaW, stage.gameAreaH);
        this.backgroundUI.registerSceneBackground('snow', AssetLoader.getTexture('game-backgrounds', 'snow'));
        this.backgroundUI.registerSceneBackground('summer', AssetLoader.getTexture('game-backgrounds', 'summer'));
        this.backgroundUI.showScene('snow');
        this.gameUI = new PIXI.Container();
        this.stage.addChild(this.backgroundUI, this.gameUI);
        this.stateModel = new GameStateModel();
        this.networkService = new NetworkService();
        this.symbolManager = new SymbolManager();
        this.registerSymbols();

        this.setupUI();
        this.animationManager = new ReelAnimationManager(this.reelContainer);
        this.setupListeners();
    }

    public registerSymbols(): void {
        const spriteKey: string = "symbols-sheet";
        this.symbolManager.registerSymbol(0, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_santa_hat")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(spriteKey, "symbol_santa_hat")]),
        );
        this.symbolManager.registerSymbol(1, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_candy_cane")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(spriteKey, "symbol_candy_cane")]),
        );
        this.symbolManager.registerSymbol(2, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_bauble")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(spriteKey, "symbol_bauble")]),
        );
        this.symbolManager.registerSymbol(3, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_gingerbread")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(spriteKey, "symbol_gingerbread")]),
        );
        this.symbolManager.registerSymbol(4, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_stocking")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(spriteKey, "symbol_stocking")]),
        );
        this.symbolManager.registerSymbol(5, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_bell")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(spriteKey, "symbol_bell")]),
        );
        this.symbolManager.registerSymbol(6, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_snow_globe")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(spriteKey, "symbol_snow_globe")]),
        );
        this.symbolManager.registerSymbol(7, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_star_tree")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(spriteKey, "symbol_star_tree")]),
        );
    }

    private setupUI(): void {
        this.reelContainer = new ReelContainer(this.symbolManager, 5, 3);
        this.gameUI.addChild(this.reelContainer);

        this.winPanel = new WinPanel();
        this.gameUI.addChild(this.winPanel);

        this.hudView = new ButtonPanel(() => {
            void this.toggleBackground();
        });
        this.hudView.setBackgroundLabel(this.currentBackground);
        this.gameUI.addChild(this.hudView);


        this.winParticleEffect = createWinCelebrationEffect();
        this.gameUI.addChild(this.winParticleEffect);


        this.hudView.position.set((this.gameUI.width - this.hudView.width) / 2, 610);
        this.reelContainer.position.set((this.gameUI.width - this.reelContainer.width) / 2, 180);
        this.winPanel.position.set(this.gameUI.width / 2, 360);
        this.winParticleEffect.position.set((this.gameUI.width - this.winParticleEffect.width) / 2, 360);

        const bounds = this.gameUI.getLocalBounds();
        this.gameUI.pivot.set(
            bounds.x + bounds.width / 2,
            bounds.y + bounds.height / 2
        );
        this.gameUI.position.set(
            this.stage.gameAreaW / 2,
            this.stage.gameAreaH / 2
        );
    }

    public init(): void {
        this.stateModel.transitionTo(GameState.IDLE);
    }

    private async toggleBackground(): Promise<void> {
        this.currentBackground = this.currentBackground === 'snow' ? 'summer' : 'snow';
        this.hudView.setBackgroundLabel(this.currentBackground);
        await this.backgroundUI.transitionToScene(this.currentBackground);
    }

    private setupListeners(): void {
        this.eventBus.on(GameEvents.USER_CLICK_SPIN, () => {
            this.onSpinButtonClick();
        });
    }

    public async onSpinButtonClick(): Promise<void> {
        if (!this.stateModel.canSpin()) {
            console.warn('[Guard]: Game is currently busy!');
            return;
        }

        this.stateModel.transitionTo(GameState.SPINNING);
        this.balance -= this.bet;
        this.hudView.setBalance(this.balance);
        this.winPanel.hide();
        const spinAnimation = this.animationManager.spinReels();
        try {
            const response = await this.networkService.requestSpinData({ betAmount: 10, lines: 20 });
            this.roundWin = response.totalWin;
            await spinAnimation;
            await this.startWinPresentaion();
            // Type-safe properties access
            console.log("Matrix Received:", response.matrix);
            console.log("Total Win Amount:", response.totalWin);

            if (response.freeSpinsTriggered) {
                console.log("Triggering Free Spins Feature Animation!");
            }
        } catch (error) {
            this.animationManager.cancelSpin();
            await spinAnimation;
            const err = error as Error;
            console.error("Spin Request Failed:", err.message);
        }
        finally {
            this.stateModel.transitionTo(GameState.IDLE);
        }

    }

    private async startWinPresentaion(): Promise<void> {
        this.stateModel.transitionTo(GameState.EVALUATING);
        this.gameRounds = [
            new WinEvaluationRound()
        ];
        for (const round of this.gameRounds) {
            await round.init();
        }
        this.balance += this.roundWin;
        this.hudView.setBalance(this.balance);
        if (this.roundWin > 0) {
            this.winPanel.showWin(this.roundWin);
            this.winParticleEffect.play();
        }

    }

}