import * as PIXI from 'pixi.js';
import { gsap } from 'gsap';
import { WinCelebrationEffect } from './WinCelebrationEffect';

export class GsapWinParticleEffect extends PIXI.Container implements WinCelebrationEffect {
    private timeline: ReturnType<typeof gsap.timeline> | null = null;
    private readonly particleColors = [0xffd166, 0xffffff, 0x00d4ff, 0xff6b6b];

    constructor() {
        super();
        this.visible = false;
        this.eventMode = 'none';
    }

    public play(): void {
        this.timeline?.kill();
        this.clearParticles();
        this.visible = true;

        this.timeline = gsap.timeline({
            onComplete: () => {
                this.clearParticles();
                this.visible = false;
                this.timeline = null;
            },
        });

        const particleCount = 36;
        for (let index = 0; index < particleCount; index += 1) {
            const particle = new PIXI.Graphics();
            const size = 4 + Math.random() * 6;
            const color = this.particleColors[index % this.particleColors.length];

            if (index % 3 === 0) {
                particle.circle(0, 0, size / 2).fill(color);
            } else {
                particle.rect(-size / 2, -size / 2, size, size).fill(color);
            }

            particle.alpha = 0;
            particle.scale.set(0.4);
            this.addChild(particle);

            const angle = (index / particleCount) * Math.PI * 2 + (Math.random() - 0.5) * 0.2;
            const distance = 90 + Math.random() * 110;
            const duration = 0.7 + Math.random() * 0.35;
            const delay = Math.random() * 0.12;

            this.timeline.to(particle, {
                alpha: 1,
                scale: 1,
                duration: 0.12,
                ease: 'power1.out',
            }, delay);
            this.timeline.to(particle, {
                x: Math.cos(angle) * distance,
                y: Math.sin(angle) * distance,
                alpha: 0,
                scale: 0.1,
                rotation: (Math.random() - 0.5) * Math.PI * 4,
                duration,
                ease: 'power2.out',
            }, delay + 0.12);
        }
    }

    private clearParticles(): void {
        this.removeChildren().forEach((particle) => particle.destroy());
    }
}
