import * as PIXI from 'pixi.js';
import { SYMBOL_HEIGHT, SYMBOL_WIDTH } from '../config/SymbolConfig';

export interface SymbolOffsets {
    x?: number;
    y?: number;
}

export class SymbolView extends PIXI.Container {
    public id: number;
    public idleSprite: PIXI.Sprite;
    public winAnimation: PIXI.AnimatedSprite;
    public offsetX: number;
    public offsetY: number;

    constructor(
        id: number = 0,
        idleSprite: PIXI.Sprite,
        winAnimation: PIXI.AnimatedSprite,
        offsets: SymbolOffsets = {},
    ) {
        super();
        this.id = id;
        this.offsetX = offsets.x ?? 0;
        this.offsetY = offsets.y ?? 0;

        this.idleSprite = idleSprite;
        this.winAnimation = winAnimation;
        this.winAnimation.animationSpeed = winAnimation.animationSpeed;
        this.winAnimation.loop = winAnimation.loop;
        this.winAnimation.updateAnchor = winAnimation.updateAnchor;

        for (const sprite of [this.idleSprite, this.winAnimation]) {
            sprite.width = SYMBOL_WIDTH;
            sprite.height = SYMBOL_HEIGHT;
        }

        this.addChild(this.idleSprite, this.winAnimation);
        this.winAnimation.visible = false;
        this.applyTint();
    }

    public setDefinition(definition: SymbolView): void {
        this.id = definition.id;
        this.idleSprite.texture = definition.idleSprite.texture;
        this.winAnimation.stop();
        this.winAnimation.textures = definition.winAnimation.textures;
        this.winAnimation.animationSpeed = definition.winAnimation.animationSpeed;
        this.winAnimation.loop = definition.winAnimation.loop;
        this.winAnimation.updateAnchor = definition.winAnimation.updateAnchor;
        this.offsetX = definition.offsetX;
        this.offsetY = definition.offsetY;
        this.applyTint();
        this.showIdle();
    }

    public showWin(): void {
        this.idleSprite.visible = false;
        this.winAnimation.visible = true;
        this.winAnimation.gotoAndPlay(0);
    }

    public showIdle(): void {
        this.winAnimation.stop();
        this.winAnimation.gotoAndStop(0);
        this.winAnimation.visible = false;
        this.idleSprite.visible = true;
    }

    private applyTint(): void {
        const tint = 0xffffff;
        this.idleSprite.tint = tint;
        this.winAnimation.tint = tint;
    }
}
