import * as PIXI from 'pixi.js';
import { WinCelebrationEffect } from './WinCelebrationEffect';

interface Particle {
    displayObject: PIXI.Graphics;
    velocityX: number;
    velocityY: number;
    rotationSpeed: number;
    age: number;
    lifetime: number;
}

export class PixiParticleWinEffect extends PIXI.Container implements WinCelebrationEffect {
    private readonly particles: Particle[] = [];
    private readonly particleColors = [0xffd166, 0xffffff, 0x00d4ff, 0xff6b6b];
    private isTicking = false;

    constructor() {
        super();
        this.visible = false;
        this.eventMode = 'none';
    }

    public play(): void {
        this.stopAndClear();
        this.visible = true;

        for (let index = 0; index < 48; index += 1) {
            const particle = this.createParticle(index);
            this.particles.push(particle);
            this.addChild(particle.displayObject);
        }

        PIXI.Ticker.shared.add(this.updateParticles);
        this.isTicking = true;
    }

    private createParticle(index: number): Particle {
        const displayObject = new PIXI.Graphics();
        const size = 4 + Math.random() * 7;
        const color = this.particleColors[index % this.particleColors.length];

        if (index % 3 === 0) {
            displayObject.circle(0, 0, size / 2).fill(color);
        } else {
            displayObject.rect(-size / 2, -size / 2, size, size).fill(color);
        }

        const angle = (index / 48) * Math.PI * 2 + (Math.random() - 0.5) * 0.25;
        const speed = 120 + Math.random() * 220;

        return {
            displayObject,
            velocityX: Math.cos(angle) * speed,
            velocityY: Math.sin(angle) * speed,
            rotationSpeed: (Math.random() - 0.5) * 8,
            age: 0,
            lifetime: 0.8 + Math.random() * 0.5,
        };
    }

    private readonly updateParticles = (ticker: PIXI.Ticker): void => {
        const deltaSeconds = ticker.deltaMS / 1000;

        for (let index = this.particles.length - 1; index >= 0; index -= 1) {
            const particle = this.particles[index];
            const displayObject = particle.displayObject;
            particle.age += deltaSeconds;

            const progress = Math.min(particle.age / particle.lifetime, 1);
            displayObject.x += particle.velocityX * deltaSeconds;
            displayObject.y += particle.velocityY * deltaSeconds + 150 * deltaSeconds * deltaSeconds;
            particle.velocityY += 300 * deltaSeconds;
            displayObject.rotation += particle.rotationSpeed * deltaSeconds;
            displayObject.alpha = 1 - progress;
            displayObject.scale.set(1 - progress * 0.65);

            if (progress >= 1) {
                this.removeChild(displayObject);
                displayObject.destroy();
                this.particles.splice(index, 1);
            }
        }

        if (this.particles.length === 0) {
            this.stopAndClear();
        }
    };

    private stopAndClear(): void {
        if (this.isTicking) {
            PIXI.Ticker.shared.remove(this.updateParticles);
            this.isTicking = false;
        }

        for (const particle of this.particles) {
            this.removeChild(particle.displayObject);
            particle.displayObject.destroy();
        }
        this.particles.length = 0;
        this.visible = false;
    }
}