import * as PIXI from 'pixi.js';
import { SymbolOffsets, SymbolView } from '../views/SymbolView';

export class SymbolManager {
    private pool: SymbolView[] = [];
    private registeredSymbols = new Map<number, SymbolView>();
    private activeSprites: Set<SymbolView> = new Set();

    public registerSymbol(
        id: number,
        idleSprite: PIXI.Sprite,
        winAnimation: PIXI.AnimatedSprite,
        offsets: SymbolOffsets = {},
    ): void {
        this.registeredSymbols.set(
            id,
            new SymbolView(id, idleSprite, winAnimation, offsets)
        );
    }

    public getSymbol(symbolId: number = 0): SymbolView {
        const definition = this.getDefinition(symbolId);
        const symbol = this.pool.pop() ?? this.createSymbol(definition);
        symbol.setDefinition(definition);
        symbol.visible = true;
        symbol.position.set(symbol.offsetX, symbol.offsetY);
        this.activeSprites.add(symbol);
        return symbol;
    }

    public applySymbol(symbol: SymbolView, symbolId: number): void {
        const definition = this.getDefinition(symbolId);
        symbol.setDefinition(definition);
        symbol.visible = true;
    }

    private getDefinition(symbolId: number): SymbolView {
        const definition = this.registeredSymbols.get(symbolId) ?? this.registeredSymbols.get(0);
        if (!definition) {
            throw new Error(`Symbol ${symbolId} is not registered and no fallback symbol is available.`);
        }

        return definition;
    }

    private createSymbol(definition: SymbolView): SymbolView {
        const idleSprite = new PIXI.Sprite(definition.idleSprite.texture);
        const winAnimation = new PIXI.AnimatedSprite(definition.winAnimation.textures);
        winAnimation.animationSpeed = definition.winAnimation.animationSpeed;
        winAnimation.loop = definition.winAnimation.loop;
        winAnimation.updateAnchor = definition.winAnimation.updateAnchor;

        return new SymbolView(
            definition.id,
            idleSprite,
            winAnimation,
            { x: definition.offsetX, y: definition.offsetY },
        );
    }

    public recycleSymbol(symbol: SymbolView): void {
        this.activeSprites.delete(symbol);
        symbol.visible = false;
        symbol.showIdle();
        symbol.position.set(0, 0);
        this.pool.push(symbol);
    }
}