import * as PIXI from 'pixi.js';
import { gsap } from 'gsap';

export type BackgroundFactory = () => PIXI.Container;
export type BackgroundSource = PIXI.Texture | BackgroundFactory;

export class BackgroundUI extends PIXI.Container {
    private readonly slots: [PIXI.Container, PIXI.Container] = [
        new PIXI.Container(),
        new PIXI.Container(),
    ];
    private readonly sceneBackgrounds = new Map<string, BackgroundFactory>();
    private activeSlot = -1;
    private cancelPendingTransition?: () => void;

    constructor(
        private readonly gameAreaW: number,
        private readonly gameAreaH: number
    ) {
        super();
        this.addChild(...this.slots);
        this.slots.forEach((slot) => {
            slot.alpha = 0;
            slot.eventMode = 'none';
        });
    }

    public registerSceneBackground(sceneId: string, source: BackgroundSource): void {
        const factory = source instanceof PIXI.Texture
            ? () => new PIXI.Sprite(source)
            : source;
        this.sceneBackgrounds.set(sceneId, factory);
    }

    public async transitionToScene(sceneId: string, duration = 0.8): Promise<void> {
        const factory = this.getSceneBackground(sceneId);
        await this.transitionToBackground(factory(), duration);
    }

    public showScene(sceneId: string): void {
        const factory = this.getSceneBackground(sceneId);
        this.showBackground(factory());
    }

    public transitionToBackground(background: PIXI.Container, duration = 0.8): Promise<void> {
        this.cancelTransition();

        const incomingIndex = this.activeSlot === 0 ? 1 : 0;
        const outgoingIndex = this.activeSlot;
        const incoming = this.slots[incomingIndex];
        this.replaceSlotContent(incoming, background);
        this.fitBackground(background);
        incoming.alpha = 0;
        this.activeSlot = incomingIndex;

        if (outgoingIndex < 0 || duration <= 0) {
            incoming.alpha = 1;
            this.clearSlot(this.slots[outgoingIndex < 0 ? 1 : outgoingIndex]);
            return Promise.resolve();
        }

        const outgoing = this.slots[outgoingIndex];
        return new Promise((resolve) => {
            let pending = true;
            const finish = () => {
                if (!pending) return;
                pending = false;
                this.cancelPendingTransition = undefined;
                this.clearSlot(outgoing);
                resolve();
            };

            this.cancelPendingTransition = () => {
                if (!pending) return;
                pending = false;
                gsap.killTweensOf([incoming, outgoing]);
                incoming.alpha = 1;
                this.clearSlot(outgoing);
                this.cancelPendingTransition = undefined;
                resolve();
            };

            gsap.to(incoming, { alpha: 1, duration, ease: 'power2.inOut' });
            gsap.to(outgoing, { alpha: 0, duration, ease: 'power2.inOut', onComplete: finish });
        });
    }

    public showBackground(background: PIXI.Container): void {
        this.cancelTransition();

        const targetIndex = this.activeSlot < 0 ? 0 : this.activeSlot;
        this.slots.forEach((slot, index) => {
            if (index !== targetIndex) this.clearSlot(slot);
        });

        const target = this.slots[targetIndex];
        this.replaceSlotContent(target, background);
        this.fitBackground(background);
        target.alpha = 1;
        this.activeSlot = targetIndex;
    }

    private getSceneBackground(sceneId: string): BackgroundFactory {
        const factory = this.sceneBackgrounds.get(sceneId);
        if (!factory) {
            throw new Error(`No background registered for scene "${sceneId}".`);
        }
        return factory;
    }

    private fitBackground(background: PIXI.Container): void {
        const bounds = background.getLocalBounds();
        if (bounds.width <= 0 || bounds.height <= 0) return;

        const scale = Math.max(
            this.gameAreaW / bounds.width,
            this.gameAreaH / bounds.height
        );
        background.pivot.set(
            bounds.x + bounds.width / 2,
            bounds.y + bounds.height / 2
        );
        background.scale.set(scale);
        background.position.set(this.gameAreaW / 2, this.gameAreaH / 2);
    }

    private replaceSlotContent(slot: PIXI.Container, background: PIXI.Container): void {
        slot.removeChildren();
        slot.addChild(background);
    }

    private clearSlot(slot: PIXI.Container): void {
        slot.removeChildren();
        slot.alpha = 0;
    }

    private cancelTransition(): void {
        this.cancelPendingTransition?.();
    }
}
